    s2.do("a", "建立", "s1", ("alice", "pw"), 0)
    s2.do("b", "建立", "s2", ("alice", "pw"), 0)
    s2.do("c", "建立", "s3", ("bob", "pw"), 0)
    bad = s2.export_config().replace('"总数":4', '"总数":2')
