        s2.config_change("rk", "加载", bad, 7)
    except ResourceError:
        pass
    else:
        raise AssertionError
    ev2 = chain(s2)
    assert [e["结果"] for e in ev2] == ["ResourceError", "重放ResourceError"], ev2
