    s3 = make()
    for _ in range(2):
        try:
            s3.config_change("bk", "回滚", None, 3)
        except StateError:
            pass
        else:
            raise AssertionError
    ev3 = chain(s3)
    assert [(e["操作"], e["结果"], e["原序号"], e["会话"]) for e in ev3] == [
        ("配置回滚", "StateError", 0, ""),
        ("配置回滚", "重放StateError", 1, ""),
    ], ev3
    assert s3.verify_audit()


