def t_rollback_success_replay():
    s = make()
    before = s.export_config()
    doc = json.loads(before)
    doc["会话"]["租期毫秒"] = 9
    s.config_change("load", "加载", json.dumps(doc, ensure_ascii=False), 1)
    out1 = s.config_change("rb", "回滚", None, 2)
    assert out1 == before
    # 回滚点已清；直接回滚应 StateError
    try:
        s.rollback_config()
    except StateError:
        pass
    else:
        raise AssertionError
    # 但同参重放返回缓存首果，不再执行业务
    out2 = s.config_change("rb", "回滚", None, 3)
    assert out2 == before
    ev = chain(s)
    assert [(e["操作"], e["结果"], e["原序号"], e["时刻"]) for e in ev] == [
        ("配置加载", "成功", 0, 1),
        ("配置回滚", "成功", 0, 2),
        ("配置回滚", "重放成功", 2, 3),
    ], ev
    assert s.verify_audit()


