def t_failure_isolation():
    s = make(pool=("10.0.0.0/24", (), ()))
    s.do("a", "建立", "s1", ("alice", "pw"), 0)
    s.fault("f", "注入", 1000, 0)
    good = s.export_config()
    bad = good.replace('"总数":4', '"总数":0')  # 值也非法（<1），ValueError
